-- =============================================================================
-- scroll.config.device: HOW TO FIND THE RIGHT INPUT DEVICE
--
-- It must be the evdev device that reports BOTH the letter keys (W/S) and the
-- Super key. If it is wrong, the scroll runs once per press and stops, because
-- the key check in scrollhold.sh never sees the keys as held (the debug log
-- shows "exit: KEY_W released" right after the first scroll).
--
-- `ls -l /dev/input/by-id/` alone CANNOT tell you which one is right: it only
-- lists names. Gaming and multimedia keyboards (and even mice) expose several
-- interfaces ("-event-kbd", "-if01-event-kbd", "-event-if01", ...), and often
-- only ONE of them reports the typing keys. You have to test them.
--
-- Step 0 - requirements
--     command -v evtest      # must print a path (pacman -S evtest)
--     id | grep -o 'input'   # must print "input"; if not:
--                            #   sudo usermod -aG input $USER  (log out and in)
--
-- Step 1 - list the candidates (names only, this does not pick one)
--     ls -l /dev/input/by-id/
--
-- Step 2 - find which device sees the keys. Paste this, press Enter, then HOLD
-- Super+W until it prints "done" (about 5 seconds):
--
--     echo "Hold Super+W for the next 5 seconds"; sleep 1
--     for round in 1 2 3 4 5; do
--       for d in /dev/input/event*; do
--         for k in KEY_W KEY_LEFTMETA KEY_RIGHTMETA; do
--           evtest --query "$d" EV_KEY $k 2>/dev/null
--           [ $? -eq 10 ] && echo "round $round: $k DOWN on $d ($(cat /sys/class/input/$(basename $d)/device/name 2>/dev/null))"
--         done
--       done
--       sleep 0.5
--     done
--     echo done
--
--   evtest --query exits with 10 while the key is down and 0 while it is up.
--   Super is pressed first, so KEY_LEFTMETA shows up from round 1 and KEY_W from
--   round 2 on; that is expected.
--
-- Step 3 - read the result
--   The right device is the one where BOTH KEY_W and KEY_LEFTMETA appear as DOWN
--   (example: /dev/input/event9). If they appear on different devices, no
--   single device works for scrollhold. If nothing appears at all, check
--   Step 0 (evtest missing or no permission).
--
-- Step 4 - convert eventN to the stable by-id path
--   Event numbers (event9) can change between boots, the by-id names do not:
--
--     ls -l /dev/input/by-id/ | grep '/event9$'
--     -> usb-SUNSONNY_GAMING_KEYBOARD-if01-event-kbd -> ../event9
--
--   Use /dev/input/by-id/<that name> below. (Note: the plain
--   "usb-SUNSONNY_GAMING_KEYBOARD-event-kbd" is NOT the one here, it was event7
--   and does not report these keys.)
--
-- Step 5 - confirm the chosen path (hold the key during the 3 seconds)
--     sleep 3; evtest --query /dev/input/by-id/<name> EV_KEY KEY_W; echo $?
--   It must print 10 while W is held. Repeat with KEY_LEFTMETA and Super.
--
-- Troubleshooting (set scroll.config.debug = true, reload, then):
--     cat /tmp/scrollhold-lua.log; echo ----; cat /tmp/scrollhold-debug.log
--   rc=127  evtest is not installed
--   rc=1 with an error message  device missing or no read permission
--   rc=0 on every query  wrong device (Step 2 again)
-- =============================================================================
-- Mouse scroll
scroll.config.device = "/dev/input/by-id/usb-SUNSONNY_GAMING_KEYBOARD-if01-event-kbd"
scroll.config.interval = "0.1"

hl.bind(mainMod .. " + W", scroll.up)
hl.bind(mainMod .. " + S", scroll.down)

-- Optional: if you release Super before W, the release bind above may not
